// DependentsWithTier is Dependents plus the honest caveat: how far the returned
// count may be trusted.
//
// The tier is the weakest edge the walk crossed, because a chain is only as
// sound as its least certain link. Two cases matter beyond that:
//
//   - the subject itself lives in a partially analysed file, so the edges that
//     would point at it may simply not exist in the graph — Unresolvable;
//   - a dependent lives in one, so the path onward from it is not visible.
//
// A zero count from an Unresolvable subject is the dangerous reading Gate used
// to print as a confident zero. It now carries its tier everywhere it goes.
func (ix *Index) DependentsWithTier(ids []string, hops int) ([]Symbol, EvidenceTier) {
	tier := Confirmed
	for _, id := range ids {
		if s, ok := ix.symbols[id]; ok {
			if _, partial := ix.partial[s.Path]; partial {
				tier = Unresolvable
			}
		}
	}

	seen := make(map[string]bool, len(ids))
	for _, id := range ids {
		seen[id] = true
	}

	var found []Symbol
	frontier := ids
	for hop := 0; hop < hops && len(frontier) > 0; hop++ {
		var next []string
		for _, id := range frontier {
			for _, edge := range ix.incoming[id] {
				if seen[edge.From] {
					continue
				}
				seen[edge.From] = true
				next = append(next, edge.From)
				tier = Weakest(tier, edge.Tier)
				// An unresolved endpoint has an ID but no definition record —
				// an external or unparsed target. It still counts as a
				// dependent, so synthesise enough of a Symbol to name it.
				if s, ok := ix.symbols[edge.From]; ok {
					if _, partial := ix.partial[s.Path]; partial {
						tier = Weakest(tier, Unresolvable)
					}
					found = append(found, s)
				} else {
					// No definition record at all: we know something points
					// here, not what it is. That is inference, not proof.
					tier = Weakest(tier, Heuristic)
					found = append(found, Symbol{ID: edge.From, Name: edge.From})
				}
			}
		}
		frontier = next
	}
	sortSymbols(found)
	return dedupeByLocation(found), tier
}"""
