20	// binary, so the product zeroes every verified entity and would sort a
21	// 9-dependent verified change below a 1-dependent unchecked one. Dependents are
22	// the risk; coverage breaks ties.
23	func ReviewOrder(entities []ChangedEntity) []ChangedEntity {
24		ordered := make([]ChangedEntity, len(entities))
25		copy(ordered, entities)
26		sort.SliceStable(ordered, func(i, j int) bool {
27			a, b := ordered[i], ordered[j]
28			if a.Dependents != b.Dependents {
29				return a.Dependents > b.Dependents
30			}
31			if (a.Coverage == Unchecked) != (b.Coverage == Unchecked) {
32				return a.Coverage == Unchecked
33			}
34			return a.Path < b.Path
35		})
36		return ordered
37	}
